void wait_ms(volatile unsigned int count) {
    while (count--) {
        __asm__ volatile ("nop");
    }
}

void uart_setup(void) {
    uint32_t rtc_freq = *reg32(&__base_regs, CHESHIRE_RTC_FREQ_REG_OFFSET);
    uint64_t reset_freq = clint_get_core_freq(rtc_freq, 2500);
    uart_init(&__base_uart, reset_freq, __BOOT_BAUDRATE);
    char init[] = "Carfield_setup ...\r\n";
    wait_ms(10000000);
    uart_write_str(&__base_uart, init, sizeof(init) - 1);
    uart_write_flush(&__base_uart);
}

int main(void){
    uart_setup();
    printf("CAN_init ...\n");
    wait_ms(10000000);
    printf("Start acquiring data ...\n");
    wait_ms(60000000);

int i;
float hrv_meannn = 0.0f;
float hrv_rmssd = 0.0f;
float hrv_lfhf = 0.0f;
    for (i = 0; i < ROWS; i++) {
        float col5  = data[i][5];   /* colonna  7 */
        float col7  = data[i][7];   /* colonna  8 */

        printf("Calculated Heart Rate: %.0f bpm", col7);

        for(int j = 0; j < 8; j++) {
            if(col5 == data[j][9]){
                hrv_meannn = data[j][11];
                hrv_rmssd = data[j][15];
                hrv_lfhf = data[j][38];
                printf("  HRV_meanNN: %.3f ms  HRV_RMSSD: %.3f ms  HRV_LFHF %.3f", hrv_meannn, hrv_rmssd, hrv_lfhf);
            }
        }
        //printf("  HRV_meanNN: %.3f ms  HRV_RMSSD: %.3f ms  HRV_LFHF %.3f", hrv_meannn, hrv_rmssd, hrv_lfhf);
        printf("\n");
        wait_ms(30000000); //corretta
        //wait_ms(3000000); //prova
    }
    return 0;
}